package net.minecraft.world.level;public class ChunkPos{public int x,z;public ChunkPos(int x,int z){this.x=x;this.z=z;}public ChunkPos(net.minecraft.core.BlockPos pos){this(pos.getX()>>4,pos.getZ()>>4);}public long toLong(){return asLong(x,z);}public ChunkPos(long p){x=(int)p;z=(int)(p>>>32);}public static long asLong(int x,int z){return (long)x&0xffffffffL|((long)z&0xffffffffL)<<32;}}